SELECT CASE WHEN ((CAST((CAST((ARRAY<INT>[1, 2, 3]) AS VARIANT)) AS VARCHAR)) = '[1,2,3]') THEN 'PASS' ELSE 'FAIL' END AS `v_array_roundtrip`, CASE WHEN ((CAST((CAST((MAP<VARCHAR,TINYINT>{'b':2,'a':1}) AS VARIANT)) AS VARCHAR)) = '{"a":1,"b":2}') THEN 'PASS' ELSE 'FAIL' END AS `v_map_roundtrip`, CASE WHEN ((CAST((CAST((row(1, 'x')) AS VARIANT)) AS VARCHAR)) = '{"col1":1,"col2":"x"}') THEN 'PASS' ELSE 'FAIL' END AS `v_struct_roundtrip`;
SELECT CASE WHEN ((CAST((CAST((ARRAY<INT>[1, 2, 3]) AS VARIANT)) AS VARCHAR)) = '[1,2,3]') THEN 'PASS' ELSE 'FAIL' END AS `v_array_roundtrip`, CASE WHEN ((CASE WHEN ((CAST((CAST((ARRAY<INT>[1, 2, 3]) AS VARIANT)) AS VARCHAR)) = '[1,2,3]') THEN 'PASS' ELSE 'FAIL' END) = '{"a":1,"b":2}') THEN 'PASS' ELSE 'FAIL' END AS `v_map_roundtrip`, CASE WHEN ((CAST((CAST((row(1, 'x')) AS VARIANT)) AS VARCHAR)) = '{"col1":1,"col2":"x"}') THEN 'PASS' ELSE 'FAIL' END AS `v_struct_roundtrip`;
SELECT CASE WHEN ((CAST((CAST((ARRAY<INT>[1, 2, 3]) AS VARIANT)) AS VARCHAR)) = '[1,2,3]') THEN 'PASS' ELSE 'FAIL' END AS `v_array_roundtrip`, CASE WHEN ((CAST((CAST((MAP<VARCHAR,TINYINT>{'b':2,'a':1}) AS VARIANT)) AS VARCHAR)) = '{"a":1,"b":2}') THEN 'PASS' ELSE 'FAIL' END AS `v_map_roundtrip`, CASE WHEN ((CAST((CAST((row(1, 'x')) AS VARIANT)) AS VARCHAR)) = '{"col1":1,"col2":"x"}') THEN 'PASS' ELSE 'FAIL' END AS `v_struct_roundtrip`;